import unittest
from merge_intervals import merge_intervals
class Tests(unittest.TestCase):
 def test_union(self):
  self.assertEqual(merge_intervals([[8,9],[1,3],[2,5],[5,8]]),[[1,9]])
 def test_empty(self): self.assertEqual(merge_intervals([]),[])
 def test_not_mutated(self):
  x=[[4,5],[1,2]];merge_intervals(x);self.assertEqual(x,[[4,5],[1,2]])
 def test_invalid(self):
  with self.assertRaises(ValueError):merge_intervals([[3,1]])
if __name__=='__main__': unittest.main()
